base64 -d /tmp/78.b64 > /tmp/78.patch
git apply --unidiff-zero /tmp/78.patch
rm -f /tmp/78.b64 /tmp/78.patch

git add -A
git commit -q -m "Alle zichtbare tekst door de vertaallaag, vlag bij de taalkeuze

Op /pl/ en /da/ stond nog overal Nederlands: de voettekst, het menu, de
shopknoppen, de homepageblokken, de pop-up. Drie oorzaken, alle drie weg.

1. De woordenlijst in src/i18n/ui.js viel voor elke taal buiten de zes
   brontalen terug op Nederlands. Loopt nu door vulAan.
2. 36 taalblokken stonden in de componenten zelf. Het vertaalscript loopt
   alleen src/data/*.js af, dus die werden nooit aangeboden aan DeepL. Ze
   staan nu in src/data/component-teksten.js, 65.000 tekens per taal.
3. De shoplabels hadden een eigen tabel buiten de vertaallaag om.

Verder: vlag plus taalnaam in de taalwisselaar, exit-intent alleen in de
talen waar de kleurentest bestaat, chatbot terug naar Engels in plaats van
Nederlands, priceValidUntil in het Product-schema, plaatshouders beschermd
in het vertaalscript, en TAAL-TOEVOEGEN.md met de werkwijze.

Co-Authored-By: Claude Opus 5 <noreply@anthropic.com>"

echo
echo "Patch 78 toegepast en vastgelegd."
git log --oneline -1
echo
echo "Volgende stap: export DEEPL_API_KEY=... en dan"
echo "  node scripts/hsf-translate-content.mjs pl da sv"
